ColorLike = Union[str, QColor]

_RENDERER_CACHE: dict = {}
_RENDERER_CACHE_MAX = 512


class AppIcon:
    __slots__ = ("name", "_variants")

    def __init__(self, name: str, variants: Dict[int, Tuple[str, str]]):
        self.name = name
        self._variants = variants

    def variant_for(self, size: int) -> int:
        """Sizes <= 16 px use the 16 px grid: sharper than a downscaled 20 px grid."""
        if size <= 16 and 16 in self._variants:
            return 16
        return 20

    def svg(self, color: ColorLike, size: int = 20) -> bytes:
        v = self.variant_for(size)
        c = QColor(color)
        opacity = ""
        if c.alpha() < 255:
            opacity = f' fill-opacity="{c.alphaF():.3f}"'
        viewbox, path = self._variants[v]
        return (
            f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{viewbox}">'
            f'<path fill="{c.name()}"{opacity} d="{path}"/></svg>'
        ).encode("ascii")

    def paint(self, painter: QPainter, rect, color: ColorLike):
        r = QRectF(rect)
        size = int(round(min(r.width(), r.height())))
        renderer = _renderer(self, QColor(color), size)
        renderer.render(painter, r)

    def qicon(self, color: ColorLike, sizes: Optional[Sequence[int]] = None) -> QIcon:
        return make_qicon(self, color, sizes)

    def __repr__(self) -> str:
        return f"AppIcon({self.name})"


def _renderer(icon: AppIcon, color: QColor, size: int) -> QSvgRenderer:
    variant = icon.variant_for(size)
    key = (icon.name, variant, color.name(QColor.HexArgb))
    r = _RENDERER_CACHE.get(key)
    if r is None:
        r = QSvgRenderer(QByteArray(icon.svg(color, size)))
        if len(_RENDERER_CACHE) < _RENDERER_CACHE_MAX:
            _RENDERER_CACHE[key] = r
    return r


class _IconSet:
    def __init__(self, data: Dict[str, Dict[int, Tuple[str, str]]]):
        self._icons = {name: AppIcon(name, variants) for name, variants in data.items()}

    def __getattr__(self, name: str) -> AppIcon:
        if name.startswith("_"):
            raise AttributeError(name)
        try:
            return self._icons[name]
        except KeyError:
            raise AttributeError(name) from None

    def __iter__(self) -> Iterator[AppIcon]:
        return iter(self._icons.values())

    def names(self):
        return list(self._icons)


FIF = _IconSet(_DATA)


_DEFAULT_SIZES = (13, 14, 15, 16, 18, 20, 22, 24, 32, 48, 64, 96)
_DEVICE_PIXEL_RATIOS = (1.0, 1.25, 1.5, 1.75, 2.0)
_QICON_CACHE: dict = {}
_QICON_CACHE_MAX = 1000


def make_qicon(icon: Union[AppIcon, QIcon], color: ColorLike,
               sizes: Optional[Sequence[int]] = None) -> QIcon:
    if isinstance(icon, QIcon):
        return icon

    qcolor = QColor(color)
    resolved = tuple(sizes) if sizes is not None else _DEFAULT_SIZES
    cache_key = (icon.name, qcolor.name(QColor.HexArgb), resolved)
    cached = _QICON_CACHE.get(cache_key)
    if cached is not None:
        return cached

    qicon = QIcon()
    for size in resolved:
        renderer = QSvgRenderer(QByteArray(icon.svg(qcolor, size)))
        for dpr in _DEVICE_PIXEL_RATIOS:
            px = max(1, math.ceil(size * dpr))
            image = QImage(px, px, QImage.Format_ARGB32)
            image.fill(Qt.transparent)
            pixmap = QPixmap.fromImage(image, Qt.NoFormatConversion)
            pixmap.setDevicePixelRatio(dpr)
            painter = QPainter(pixmap)
            try:
                painter.setRenderHint(QPainter.Antialiasing, True)
                painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
                renderer.render(painter, QRectF(0, 0, size, size))
            finally:
                painter.end()
            qicon.addPixmap(pixmap)

    if len(_QICON_CACHE) < _QICON_CACHE_MAX:
        _QICON_CACHE[cache_key] = qicon
    return qicon
